import {$,esc,icon,toast} from '/shared/ui.js';
import {campusMap,inCampus} from '/shared/map.js';
import {distance,direction,meters} from '/shared/routing.js';
import {routeSteps,guidance} from '/shared/guidance.js';
import {mapApps} from '/shared/map-apps.js';

export function journeyHTML(catalog,targetId){const points=catalog.points.filter(p=>p.open),options=selected=>points.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');return `<section class="journey-heading"><div><span class="eyebrow">CAMPUS WALK / 校园步行</span><h1>想去哪里？<span>我们一起走。</span></h1><p>选好目的地，先看路线，再从身边的小路出发。</p></div><a href="#routes" class="button secondary">${icon('camera')} 选一段拍摄探索</a></section><div class="journey-layout"><section class="journey-controls"><div class="journey-addresses"><span class="journey-thread" aria-hidden="true"></span><label class="journey-address"><b class="address-dot start"></b><span>从哪里出发<select id="journey-from"><option value="">请选择起点</option><option value="gps">我的当前位置</option><option value="pick">在地图上选起点</option>${options('')}</select></span></label><label class="journey-address"><b class="address-dot end"></b><span>想去哪里<select id="journey-to"><option value="">请选择目的地</option>${options(targetId)}</select></span></label></div><div class="journey-action-row"><button class="button secondary" id="journey-gps">${icon('pin')} 用我的位置</button><button class="button secondary" id="journey-pick">地图选起点</button></div><p class="journey-message" id="journey-message" role="status">可选择校园点位作为起点，不开定位也能查看路线。</p><button class="button wide" id="journey-plan">${icon('walk')} 规划步行路线</button><section class="journey-result" id="journey-result" hidden><div class="journey-stats"><strong id="journey-time"></strong><span id="journey-distance"></span><small>步行估算 · 约 4.5 公里 / 小时</small></div><div class="journey-live"><b id="journey-symbol" aria-hidden="true">↑</b><p id="journey-instruction" aria-live="polite">路线已准备好</p></div><div class="journey-progress" aria-label="路线行进进度"><span id="journey-progress"></span></div><button class="button wide" id="journey-start">开始网页导航</button><div class="journey-action-row"><button class="button secondary" id="journey-follow">跟随位置：开</button><button class="button secondary" id="journey-voice">语音提示：关</button></div><details class="journey-steps"><summary>查看转向步骤</summary><ol id="journey-steps"></ol></details><p class="muted">实线沿公开道路，虚线是靠近点位的示意，请确认现场入口。仅支持校内步行，不包含实时封路信息。</p></section><button class="text-btn wide" id="journey-apps">用手机地图 App / 网页版打开 ↗</button><p class="journey-privacy">定位仅用于本页导航，不上传、不保存。离开页面或切到后台会停止。需保持浏览器在前台。</p></section><section class="journey-map-panel"><div id="journey-map" class="map-canvas" role="region" aria-label="校园步行路线规划地图"></div><div class="journey-map-top"><span>${icon('walk')} 步行 · 北方民族大学</span><button class="button secondary small" id="journey-overview">全校范围</button></div><div class="journey-map-caption"><i></i>沿道路步行 <span>··· 靠近点位，请确认入口</span></div></section></div><p class="journey-data" id="journey-data"></p>`;}

export async function mountJourney(catalog){
 const el=$('#journey-map'),map=await campusMap(el,catalog,{canPick:()=>picking,onPick:p=>{if(!picking||destroyed)return false;if(!inCampus(p,catalog.campus)){message('请在北方民族大学校区内选择起点');return false;}stop();origin={...p,name:'地图选定起点'};picking=false;$('#journey-from').value='pick';message('起点已选择，可以规划路线');plan();},onPoint:id=>{if(picking){const p=catalog.points.find(p=>p.id===id);stop();origin=p;picking=false;$('#journey-from').value=id;message('已选起点：'+p.name);plan();}else{$('#journey-to').value=id;stop();plan();}}});
 if(!el.isConnected){map.destroy();return {destroy(){},refresh(){}};}
 let origin=null,position=null,leg=null,picking=false,watch=null,token=0,destroyed=false,follow=true,voice=false,lastSpoken='',lastSpeechAt=0,offCount=0,permissionPending=false,oneShot=0;
 const from=$('#journey-from'),to=$('#journey-to'),result=$('#journey-result'),start=$('#journey-start');
 const message=text=>{$('#journey-message').textContent=text;};
 const target=()=>catalog.points.find(p=>p.id===to.value&&p.open);
 function silence(){if(voice)window.speechSynthesis?.cancel();lastSpoken='';}
 function stop(){token++;if(watch!==null){navigator.geolocation?.clearWatch(watch);watch=null;}permissionPending=false;silence();start.textContent='开始网页导航';start.disabled=!leg?.available;}
 function invalidate(){stop();leg=null;result.hidden=true;map.navigation(null);}
 function describe(){const total=leg.lengthWithApproach;$('#journey-time').textContent=Math.max(1,Math.ceil(total/75))+' 分钟';$('#journey-distance').textContent=meters(total);$('#journey-instruction').textContent='路线已准备好，开启定位后为你指路';$('#journey-symbol').textContent='↑';$('#journey-progress').style.width='0%';const steps=routeSteps(leg.path);$('#journey-steps').innerHTML=`<li>从起点朝${direction(leg.path[0],leg.path[1]||target()).name}沿道路出发</li>`+steps.map(s=>`<li>${s.symbol} 行进至约 ${meters(s.along)} 处${s.action}</li>`).join('')+`<li>到达道路终点后，确认 ${esc(target().name)} 的现场入口${leg.approach>20?'（存在虚线靠近段）':''}</li>`;start.disabled=false;result.hidden=false;}
 function plan(){invalidate();const dest=target();if(!origin){message('先选择起点，或点击「用我的位置」');return;}if(!dest){message('请选择开放的目的地');return;}if(!inCampus(origin,catalog.campus)){message('当前位置在校园外，校内规划暂不可用。可用地图 App 前往校园。');return;}if(distance(origin,dest)<5){message('起点与目的地相同，请换一个目的地');return;}leg=map.plan(origin,dest);if(!leg.available){message(leg.reason+'。请选择其他起点或使用地图 App。');start.disabled=true;return;}describe();message('路线已规划。蓝线沿已知道路，虚线段需要确认现场入口。');}
 function gpsError(error){message(error.code===1?'定位权限未开启，可在浏览器设置中允许；也可以手动选起点。':'暂时无法获得位置，请到室外重试或手动选起点。');}
 function usePosition(){if(!navigator.geolocation){message('浏览器不支持定位，请手动选起点');return;}invalidate();const id=++oneShot;permissionPending=true;message('正在获取位置，请允许浏览器定位…');$('#journey-gps').disabled=true;navigator.geolocation.getCurrentPosition(pos=>{if(destroyed||id!==oneShot)return;permissionPending=false;$('#journey-gps').disabled=false;const p={lng:pos.coords.longitude,lat:pos.coords.latitude,accuracy:pos.coords.accuracy,name:'当前位置',at:pos.timestamp};position=p;map.locate(p);if(p.accuracy>80){origin=null;message('定位精度约 '+Math.round(p.accuracy)+' 米，请到室外重试。暂不使用此位置规划。');return;}origin=p;from.value='gps';picking=false;plan();},e=>{if(destroyed||id!==oneShot)return;permissionPending=false;$('#journey-gps').disabled=false;gpsError(e);},{enableHighAccuracy:true,timeout:20000,maximumAge:3000});}
 function say(text){if(!voice||!window.speechSynthesis||lastSpoken===text||Date.now()-lastSpeechAt<12000)return;lastSpoken=text;lastSpeechAt=Date.now();window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='zh-CN';utterance.rate=.95;window.speechSynthesis.speak(utterance);}
 function update(pos){if(destroyed||!target())return;position={lng:pos.coords.longitude,lat:pos.coords.latitude,accuracy:pos.coords.accuracy,at:pos.timestamp,name:'当前位置'};map.locate(position,{follow});if(!inCampus(position,catalog.campus)){offCount=0;$('#journey-instruction').textContent='你在校园范围外，校内导航已停止。可使用地图 App。';stop();return;}let info=guidance(leg,position,target());if(!info.valid){offCount=0;$('#journey-instruction').textContent=info.text;$('#journey-symbol').textContent='…';silence();return;}if(info.offRoute){offCount++;if(offCount>=2){leg=map.plan(position,target(),{fit:false});offCount=0;if(!leg.available){$('#journey-instruction').textContent='附近道路资料未连通，导航已停止，请使用地图 App。';stop();return;}origin=position;from.value='gps';describe();info=guidance(leg,position,target());message('已根据当前位置重新规划路线');}else{info.text='位置偏离参考路线，正在确认下一次定位…';}}else offCount=0;$('#journey-instruction').textContent=info.text;$('#journey-symbol').textContent=info.symbol||'↑';if(info.progress)$('#journey-progress').style.width=Math.min(100,Math.round(info.progress.along/(info.progress.total||1)*100))+'%';if(info.remaining!==undefined){$('#journey-distance').textContent='剩余约 '+meters(info.remaining);$('#journey-time').textContent=Math.max(1,Math.ceil(info.remaining/75))+' 分钟';}if(!info.offRoute)say(info.text);if(info.arrived){stop();$('#journey-progress').style.width='100%';message('本次导航已结束。请确认现场入口；探索任务需要自行完成。');}start.textContent=watch===null?'开始网页导航':'结束网页导航';}
 function begin(){if(watch!==null){stop();message('网页导航已停止，路线仍可查看');return;}if(!leg?.available||!target())return;if(!navigator.geolocation){message('浏览器不支持定位，可以查看路线或使用地图 App');return;}const id=++token;start.textContent='结束网页导航';$('#journey-instruction').textContent='正在请求定位，请允许浏览器访问位置…';watch=navigator.geolocation.watchPosition(p=>{if(destroyed||id!==token)return;update(p);},e=>{if(destroyed||id!==token)return;stop();gpsError(e);$('#journey-instruction').textContent='定位中断，导航已停止。可重试或查看路线步骤。';},{enableHighAccuracy:true,maximumAge:2000,timeout:20000});message('导航已开启。请保持页面在前台，位置不会保存。');}
 function cancelPending(){oneShot++;$('#journey-gps').disabled=false;permissionPending=false;}
 from.onchange=()=>{cancelPending();invalidate();picking=false;origin=null;if(from.value==='gps')usePosition();else if(from.value==='pick'){picking=true;message('点击地图中的道路或点位，选择出发位置');}else{origin=catalog.points.find(p=>p.id===from.value&&p.open)||null;plan();}};
 to.onchange=()=>{stop();plan();};$('#journey-plan').onclick=plan;$('#journey-gps').onclick=usePosition;$('#journey-pick').onclick=()=>{cancelPending();invalidate();origin=null;picking=true;from.value='pick';message('点击地图中的道路或点位，选择出发位置');};start.onclick=begin;
 $('#journey-apps').onclick=()=>{const dest=target();if(!dest){message('先选一个目的地，再用地图打开');return;}mapApps(dest,watch!==null&&position?.accuracy<=80?position:origin);};$('#journey-overview').onclick=()=>map.overview();$('#journey-follow').onclick=e=>{follow=!follow;e.currentTarget.textContent='跟随位置：'+(follow?'开':'关');if(follow&&position)map.locate(position);};$('#journey-voice').onclick=e=>{if(!window.speechSynthesis){toast('当前浏览器不支持语音提示');return;}voice=!voice;e.currentTarget.textContent='语音提示：'+(voice?'开':'关');if(voice){lastSpeechAt=0;say('语音提示已开启');}else{window.speechSynthesis.cancel();lastSpoken='';}};
 const hidden=()=>{if(document.hidden&&(watch!==null||permissionPending)){cancelPending();stop();message('页面已切到后台，定位已停止。返回后请重新开启导航。');}},unload=()=>{stop();oneShot++;};document.addEventListener('visibilitychange',hidden);window.addEventListener('pagehide',unload);
 const metadata=map.metadata;$('#journey-data').textContent=metadata?`道路资料：OpenStreetMap · 获取于 ${metadata.fetchedAt.slice(0,10)} · ${metadata.roadCount} 段道路；其中最近的道路编辑于 ${metadata.latestRoadEdit?.slice(0,10)||'未知'}。获取时间不代表道路实地更新，未包含校内施工及临时封闭信息。`:'道路资料：OpenStreetMap，以现场通行条件为准。';
 return {destroy(){if(destroyed)return;destroyed=true;oneShot++;stop();document.removeEventListener('visibilitychange',hidden);window.removeEventListener('pagehide',unload);map.destroy();},refresh(next){catalog=next;const dest=target();if(to.value&&!dest){invalidate();message('该目的地已下线或关闭，请选择其他点位');}if(origin?.id&&!catalog.points.some(p=>p.id===origin.id&&p.open)){origin=null;invalidate();message('原起点已关闭，请重新选起点');}}};
}
